package ru.neverland.townyjustice;
import java.util.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.java.JavaPlugin;
import com.palmergames.bukkit.towny.TownyAPI;
import ru.neverland.core.*;
/** Private case materials; all controls only browse, never create a fine or change a payment. */
public final class JusticeDossiersMenu implements Listener {
    private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm 'МСК'").withZone(ZoneId.of("Europe/Moscow"));
    private final JavaPlugin plugin;private final JusticeService justice;private final JusticeDossiersService dossiers;
    public static final class Holder implements InventoryHolder{final UUID viewer,caseId;final String mode;final int page;final Map<Integer,UUID> cases=new HashMap<>();Inventory inventory;Holder(UUID viewer,UUID caseId,String mode,int page){this.viewer=viewer;this.caseId=caseId;this.mode=mode;this.page=page;}public Inventory getInventory(){return inventory;}}
    public JusticeDossiersMenu(JavaPlugin plugin,JusticeService justice){this.plugin=plugin;this.justice=justice;this.dossiers=justice.dossiers();}
    private static String who(UUID id){if(id==null)return "не назначен";var r=TownyAPI.getInstance().getResident(id);return r==null?id.toString().substring(0,8):r.getName();}
    private static String at(long time){return DATE.format(Instant.ofEpochMilli(time));}
    private static ItemStack item(Material type,String name,List<String> lore){var s=new ItemStack(type);var m=s.getItemMeta();m.setDisplayName(MenuStyle.nameLegacy("&b"+name));m.setLore(MenuStyle.loreStrings(lore.stream().map(v->"&7"+v).toList()));m.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);s.setItemMeta(m);return s;}
    private static List<String> wrap(String text){var result=new ArrayList<String>();String rest=text;while(!rest.isEmpty()&&result.size()<16){int cut=Math.min(rest.length(),48);if(cut<rest.length()){int space=rest.lastIndexOf(' ',cut);if(space>0)cut=space;}result.add(rest.substring(0,cut));rest=rest.substring(cut).stripLeading();}return result;}
    private Holder frame(Player p,UUID id,String mode,int page,String title){var h=new Holder(p.getUniqueId(),id,mode,Math.max(0,page));h.inventory=MenuStyle.inventory(plugin,h,54,title);h.inventory.setItem(45,item(Material.ARROW,"Назад",List.of()));h.inventory.setItem(49,item(Material.SUNFLOWER,"Обновить",List.of("Просмотр не изменяет дело.")));return h;}
    public void open(Player p,UUID id,String mode,int page){try(var guard=SuiteState.guard()){
        if(id==null){var entries=dossiers.cases(p);int current=Math.min(Math.max(0,page),Math.max(0,(entries.size()-1)/36));var h=frame(p,null,"list",current,"Мои разбирательства");h.inventory.setItem(4,item(Material.WRITTEN_BOOK,"Материалы и апелляции",List.of("Ваши дела и дела, к которым у вас есть доступ.","Подозрение и связь с происшествием не доказывают вину.")));for(int i=current*36;i<Math.min(entries.size(),current*36+36);i++){var c=entries.get(i);int slot=9+i%36;h.cases.put(slot,c.id());h.inventory.setItem(slot,item(Material.PAPER,who(c.subject())+" · "+c.id().toString().substring(0,8),List.of(JusticeMenu.phase(c.phase()),at(c.created()),"Открыть материалы и историю.")));}if(entries.isEmpty())h.inventory.setItem(22,item(Material.BOOK,"Доступных дел нет",List.of()));pages(h,current,entries.size());p.openInventory(h.inventory);return;}
        var view=dossiers.view(p,id);var c=view.original();var d=view.dossier();var h=frame(p,id,mode,page,"Материалы · "+id.toString().substring(0,8));h.inventory.setItem(4,item(Material.WRITTEN_BOOK,"Дело: "+who(c.subject()),List.of("Исходное решение: "+JusticeMenu.phase(c.phase()),"Срок и сумма исходного дела не изменены.","Ответственный: "+who(d.assigned()),"Материалы не публикуются в общем розыске.")));
        if(!view.available()){h.inventory.setItem(22,item(Material.BARRIER,"Материалы пока недоступны",List.of(view.issue(),"Это не новое нарушение и не штраф.")));p.openInventory(h.inventory);return;}
        if(mode.equals("history")){var entries=new ArrayList<>(d.history());Collections.reverse(entries);int current=Math.min(Math.max(0,page),Math.max(0,(entries.size()-1)/36));h=frame(p,id,mode,current,"История решений");h.inventory.setItem(4,item(Material.WRITTEN_BOOK,"Исходное решение",List.of("Выдал: "+who(c.issuer()),at(c.created()),c.reason(),"Состояние сейчас: "+JusticeMenu.phase(c.phase()),"Ниже — новые действия в материалах дела.")));for(int i=current*36;i<Math.min(entries.size(),current*36+36);i++){var e=entries.get(i);var lore=new ArrayList<>(List.of("Автор: "+who(e.actor()),at(e.at())));lore.addAll(wrap(e.detail()));h.inventory.setItem(9+i%36,item(Material.PAPER,action(e.action()),lore));}if(entries.isEmpty())h.inventory.setItem(22,item(Material.BOOK,"Новых решений пока нет",List.of("Исходное взыскание показано выше.")));pages(h,current,entries.size());}
        else if(mode.equals("evidence")){var entries=d.evidence().values().stream().sorted(Comparator.comparingLong(JusticeDossiers.Evidence::at).reversed().thenComparing(JusticeDossiers.Evidence::id)).toList();for(int i=0;i<entries.size();i++){var e=entries.get(i);var lore=new ArrayList<>(List.of("Добавил: "+who(e.addedBy()),at(e.at()),"ID: "+e.id()));lore.addAll(wrap(e.description()));lore.add("Эти сведения сами по себе не устанавливают вину.");h.inventory.setItem(9+i,item(e.source().equals("CRIME")?Material.SPYGLASS:Material.PAPER,e.source().equals("CRIME")?"Подтверждённое происшествие":"Пояснение участника",lore));}if(entries.isEmpty())h.inventory.setItem(22,item(Material.BOOK,"Сведения пока не добавлены",List.of("Команды добавления показаны в карточке дела.")));}
        else if(mode.equals("appeals")){var entries=new ArrayList<>(d.appeals());Collections.reverse(entries);for(int i=0;i<entries.size();i++){var a=entries.get(i);var lore=new ArrayList<>(List.of("Подал: "+who(a.actor()),at(a.at())));lore.addAll(wrap(a.reason()));if(a.outcome()!=JusticeDossiers.Outcome.OPEN){lore.add("Рассмотрел: "+who(a.reviewer()));lore.add(at(a.reviewed()));lore.addAll(wrap(a.decision()));}lore.add("Взыскание меняется отдельной отменой/освобождением.");h.inventory.setItem(9+i,item(Material.WRITABLE_BOOK,outcome(a.outcome()),lore));}if(entries.isEmpty())h.inventory.setItem(22,item(Material.BOOK,"Апелляций пока нет",List.of("Подать может участник, которому назначено взыскание.")));}
        else{h.inventory.setItem(20,item(Material.SPYGLASS,"Сведения по делу",List.of("Записей: "+d.evidence().size(),"Пояснения сторон и подтверждённые происшествия.","Нажмите, чтобы прочитать.")));h.inventory.setItem(22,item(Material.WRITABLE_BOOK,"Апелляции",List.of("Заявлений: "+d.appeals().size(),d.appeals().isEmpty()?"Не подана":outcome(d.appeals().get(d.appeals().size()-1).outcome()),"Рассматривает другой уполномоченный суда.")));h.inventory.setItem(24,item(Material.CLOCK,"История решений",List.of("Автор, дата и объяснение каждого действия.","Исходное решение также сохранено.")));h.inventory.setItem(31,item(Material.FEATHER,"Как добавить материалы",List.of("Нажмите: команды пояснения, апелляции и назначения.","Новые записи действуют после подтверждения сохранения.","Апелляция не списывает и не возвращает деньги.")));}
        p.openInventory(h.inventory);
    }}
    private void pages(Holder h,int page,int count){if(page>0)h.inventory.setItem(48,item(Material.ARROW,"Предыдущая страница",List.of()));if((page+1)*36<count)h.inventory.setItem(50,item(Material.ARROW,"Следующая страница",List.of()));}
    private static String outcome(JusticeDossiers.Outcome o){return switch(o){case OPEN->"Ожидает рассмотрения";case UPHELD->"Взыскание оставлено в силе";case RECONSIDER->"Назначен пересмотр — нужна отдельная отмена";};}
    private static String action(String action){return switch(action){case "ASSIGNED"->"Назначен ответственный";case "EVIDENCE"->"Добавлены сведения";case "APPEALED"->"Подана апелляция";case "UPHELD"->"Взыскание оставлено в силе";case "RECONSIDER"->"Назначен пересмотр";default->"Запись";};}
    public static void help(Player p,UUID id){String key=id.toString();p.sendMessage("§e/justice evidence "+key+" note <пояснение>");p.sendMessage("§e/justice evidence "+key+" incident <UUID происшествия>");p.sendMessage("§e/justice appeal "+key+" <почему просите пересмотр>");p.sendMessage("§7Уполномоченному суда: /justice assign "+key+" <житель>");p.sendMessage("§7Другому уполномоченному: /justice review "+key+" uphold|reconsider <обоснование>");p.sendMessage(ru.neverland.core.EditableMessages.text(JusticeDossiersMenu.class, "§7reconsider сохраняет решение о пересмотре; отмена/освобождение выполняются отдельно штатными cancel/release."));}
    @EventHandler public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder()instanceof Holder h))return;e.setCancelled(true);if(!(e.getWhoClicked()instanceof Player p)||!p.getUniqueId().equals(h.viewer))return;int slot=e.getRawSlot();if(slot<0||slot>=54||h.inventory.getItem(slot)==null)return;SuiteScheduler.entity(plugin,p,()->{if(!p.isOnline()||p.getOpenInventory().getTopInventory()!=h.inventory)return;try{if(h.caseId!=null)dossiers.view(p,h.caseId);else dossiers.cases(p);if(slot==45){if(h.caseId==null)p.closeInventory();else open(p,h.mode.equals("detail")?null:h.caseId,"detail",0);}else if(slot==49||slot==48||slot==50)open(p,h.caseId,h.mode,h.page+(slot==48?-1:slot==50?1:0));else if(h.cases.containsKey(slot))open(p,h.cases.get(slot),"detail",0);else if(h.caseId!=null&&h.mode.equals("detail")){if(slot==20||slot==22||slot==24)open(p,h.caseId,slot==20?"evidence":slot==22?"appeals":"history",0);else if(slot==31)help(p,h.caseId);}}catch(Exception error){p.closeInventory();p.sendMessage("§cМатериалы дела: "+error.getMessage());}});}
    @EventHandler public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder()instanceof Holder)e.setCancelled(true);}
}
